// CRITICAL: Token in localStorage
localStorage.setItem('token', response.jwt)

// CRITICAL: IDOR -- any user's data accessible
app.get('/api/users/:id', async (req, res) => {
  const user = await db.users.get(req.params.id) // No ownership check!
  res.json(user)
})

// CRITICAL: Role check in business logic, not guard
async function deleteProject(userId: string, projectId: string) {
  const user = await getUser(userId)
  if (user.role === 'admin') {  // Inline authz
    await db.projects.delete(projectId)
  }
}

// CRITICAL: Secret in code
const STRIPE_KEY = 'sk_live_abc123...'

// Auth at middleware layer, not in business logic
router.delete('/projects/:id',
  authenticate(),                           // AuthN first
  authorize('project', 'delete'),           // AuthZ at gate
  ownershipCheck('project', 'params.id'),   // IDOR prevention
  deleteProjectHandler,                     // Clean handler
)

async function deleteProjectHandler(ctx: AuthenticatedContext) {
  // No auth logic here. Just business logic.
  await projectService.delete(ctx.params.id)
}

// Token: httpOnly cookie, short-lived
res.cookie('access_token', jwt, {
  httpOnly: true,
  secure: true,
  sameSite: 'strict',
  maxAge: 15 * 60 * 1000, // 15 min
})
